/**
 * Link version 2, frozen: the settings, config, log and update shapes the channels carry.
 *
 * Written out as concrete types, copied from the shapes the app resolved when link version 2 was cut. It never
 * references the living types, so a change to a handler cannot move it. Do not edit this file to match a changed
 * handler: a change that breaks it needs a new LINK_VERSION and a new `contract/v<N>/` (see protocol.ts for the
 * rule). `tests/remote/contractV2.test.ts` checks the living types against it.
 */

import type { ChallengeValuesV2 } from './shapesChallenges';

export type UpdateSummaryV2 = {
    currentVersion: string;
    latestVersion: string;
    releaseNotes: string;
    releaseDate: null | string;
    isPrerelease: boolean;
};

type ImportRefV2 = {
    holder:
        | { kind: 'rule'; number: number; title?: string }
        | { kind: 'profile'; name: string }
        | { kind: 'challenge'; id: string; title?: string };
    refers: 'profile' | 'scenario';
    name: string;
    invalid?: true;
};

export type ImportReportV2 = { at: string; refsBlocked: (string | ImportRefV2)[]; acknowledged: boolean };

export type LogEntryV2 = {
    seq: number;
    level: 'DEBUG' | 'INFO' | 'WARN' | 'ERROR';
    context: string;
    category: string;
    timestamp: string;
    message: string;
    data: unknown;
    template?: { key: string; params: unknown[] };
};

export type SettingValuesV2V2 = { [key: string]: unknown };

type ChallengePinsV2V2 = { boost?: string; turbo?: string };

export type ChallengeRecordV2V2 = { values?: SettingValuesV2V2; suppressRuleProfile?: true; pins?: ChallengePinsV2V2 };

export type TitleRuleV2 = {
    [key: string]: unknown;
    name?: string;
    title?: string;
    titles?: string[];
    match?: string;
    titleMatchModes?: string[];
    challengeTag?: string;
    type?: string;
    pics?: number;
    minHours?: number;
    maxHours?: number;
    closesAt?: string;
    closesAtTimes?: string[];
    profile?: string;
    mustIncludeTags?: string[];
    shouldIncludeTags?: string[];
};

export type WindowBoundsV2 = { x?: number; y?: number; width: number; height: number };

export type ConfigAppV2 = {
    [key: string]: unknown;
    mock: boolean;
    onboardingCompleted: boolean;
    windowBounds: { login: WindowBoundsV2; main: WindowBoundsV2 };
    theme: string;
    language: string;
    timezone: string;
    customTimezones: string[];
    stayLoggedIn: boolean;
    apiTimeout: number;
    checkFrequencyMin: number;
    checkFrequencyMax: number;
    apiMaxRetries: number;
    apiRetryBaseDelayMs: number;
};

type ImportReportV2V2 = { refsBlocked: (string | ImportRefV2)[] };

export type ImportedV2V2 = {
    at: string;
    report: ImportReportV2V2;
    acknowledged: boolean;
    failure?: { reason: string; detail: string };
};

export type SettingsRecoveryV2 = {
    code: 'settings-import-failed' | 'settings-unreadable' | 'settings-corrupt';
    path: string;
    blocking: boolean;
    detail?: string;
};

export type SettingsSaveDroppedV2 = {
    code: 'settings-save-dropped';
    path: string;
    cause: 'conflict' | 'too-large' | 'storage' | 'logout-lost';
    serial: number;
};

export type SerializableSchemaEntryV2 = {
    default?: unknown;
    type?: string;
    description: string;
    perChallenge?: boolean;
    group?: string;
    label: string;
    helpKey?: string;
    min?: number;
    max?: number;
    unit?: string;
    minutes?: boolean;
    challengeOnly: boolean;
};

export type RuleMatchChallengeV2 = {
    id?: string | number;
    title?: unknown;
    tags?: unknown;
    type?: unknown;
    max_photo_submits?: unknown;
    start_time?: unknown;
    close_time?: unknown;
};

type RuleSourceV2 = { title?: string; index: number; viaProfile?: boolean };

export type TitleRuleInfoV2 = {
    profile: null | { name: string; values: ChallengeValuesV2 };
    suppressed: boolean;
    ruleValues: ChallengeValuesV2;
    inlineValues: ChallengeValuesV2;
    ruleSources: { [key: string]: RuleSourceV2 };
    inlineSources: { [key: string]: RuleSourceV2 };
};

type ConfigAuthV2V2 = { token: string; apiHeaders: { [key: string]: string }; lastUsername: string };

export type ConfigV2V2 = {
    version: 2;
    imported?: ImportedV2V2;
    app: ConfigAppV2;
    auth: ConfigAuthV2V2;
    defaults: SettingValuesV2V2;
    profiles: { [key: string]: unknown };
    seededProfiles: string[];
    scenarios: { [key: string]: unknown };
    rules: TitleRuleV2[];
    challenges: { [key: string]: ChallengeRecordV2V2 };
};

export type DownloadProgressV2 = { percent: number; transferred: number; total: number; bytesPerSecond: number };

export type GuiLogEntryV2 = {
    message: string;
    category: string;
    seq: number;
    level: 'DEBUG' | 'INFO' | 'WARN' | 'ERROR';
    context: string;
    timestamp: string;
    template?: { key: string; params: unknown[] };
};

export type AutovoteStateV2 = {
    running: boolean;
    cycles: number;
    lastRun: null | string;
    nextRunAt: null | number;
    pendingStartAt: null | number;
    status: 'Error' | 'Stopped' | 'Running';
    statusClass: 'badge-neutral' | 'badge-success' | 'badge-error';
    error: null | string;
};
